function rounded(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function drawCrew(c){ctx.save();ctx.translate(c.x-camera.x,c.y-camera.y);ctx.rotate(c.angle);ctx.globalAlpha=c.alive?1:.45;
 // little boots and soft shadow
 ctx.fillStyle='#061017';ctx.beginPath();ctx.ellipse(0,14,18,8,0,0,TAU);ctx.fill();ctx.fillStyle='#27353a';ctx.fillRect(-12,10,8,10);ctx.fillRect(4,10,8,10);
