 if(c.state==='chase'){ctx.rotate(-c.angle);ctx.fillStyle='#ff5964';ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.fillText('!',0,-31)}ctx.restore()}
function drawPlayer(){ctx.save();ctx.translate(player.x-camera.x,player.y-camera.y);ctx.rotate(player.angle);ctx.fillStyle='#02090d88';ctx.beginPath();ctx.ellipse(1,14,20,8,0,0,TAU);ctx.fill();ctx.fillStyle='#26363d';ctx.fillRect(-12,10,8,11);ctx.fillRect(4,10,8,11);ctx.fillStyle='#c8f26b';rounded(-17,-18,34,36,14);ctx.fill();ctx.fillStyle='#90bd48';rounded(-22,-9,9,19,4);ctx.fill();ctx.fillStyle='#152a30';rounded(-8,-24,20,16,7);ctx.fill();ctx.fillStyle='#7edce4';rounded(-6,-22,16,11,5);ctx.fill();ctx.fillStyle='#e2ffff';ctx.fillRect(-4,-20,5,2);ctx.restore();
 // proximity ring highlights target
 if(nearCrew){ctx.beginPath();ctx.arc(nearCrew.x-camera.x,nearCrew.y-camera.y,27,0,TAU);ctx.strokeStyle='#c8f26b88';ctx.lineWidth=1.5;ctx.stroke()}}
function draw(){ctx.clearRect(0,0,cw,ch);ctx.fillStyle='#0a171e';ctx.fillRect(0,0,cw,ch);ctx.save();ctx.translate(-camera.x,-camera.y);
 // station base and subtle deck grid
 ctx.fillStyle='#0d1d24';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#9bb7b408';ctx.lineWidth=1;for(let x=0;x<W;x+=60){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<H;y+=60){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}
 // room floors
 for(let r of rooms){ctx.fillStyle=r.color;ctx.fillRect(r.x,r.y,r.w,r.h);ctx.fillStyle='#ffffff08';ctx.fillRect(r.x+8,r.y+8,r.w-16,3);ctx.strokeStyle='#77939b55';ctx.lineWidth=3;ctx.strokeRect(r.x,r.y,r.w,r.h);ctx.fillStyle='#e6f4f533';ctx.font='10px monospace';ctx.fillText(r.name,r.x+18,r.y+24)}
 // central transit strips
 ctx.fillStyle='#10242a';ctx.fillRect(560,70,90,1100);ctx.fillRect(1150,70,90,1100);ctx.fillRect(80,370,1640,510);ctx.fillStyle='#60787d';ctx.globalAlpha=.2;for(let x=590;x<640;x+=18){ctx.fillRect(x,385,3,480);ctx.fillRect(x,90,3,270)}ctx.globalAlpha=1;
 // wall edges / access panels
 for(let o of obstacles){ctx.fillStyle='#263c42';rounded(o.x,o.y,o.w,o.h,8);ctx.fill();ctx.strokeStyle='#68808766';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#9bb0b522';ctx.fillRect(o.x+9,o.y+8,o.w-18,4);ctx.fillStyle='#c8f26b66';ctx.fillRect(o.x+o.w-12,o.y+o.h/2-3,4,6)}
 // consoles
 for(let p of [{x:460,y:620},{x:900,y:420},{x:1330,y:620},{x:900,y:800}]){ctx.fillStyle='#293d43';rounded(p.x-17,p.y-12,34,24,5);ctx.fill();ctx.fillStyle='#7cddd2';ctx.fillRect(p.x-10,p.y-5,20,3);ctx.fillStyle='#c8f26b88';ctx.fillRect(p.x-6,p.y+2,12,2)}
 // vision haze, seen from crew
 for(let c of crew)if(c.alive&&blackout<=0){ctx.beginPath();ctx.moveTo(c.x,c.y);ctx.arc(c.x,c.y,120,c.angle-.62,c.angle+.62);ctx.closePath();ctx.fillStyle=c.state==='chase'?'#ff59640c':'#d6f1e806';ctx.fill()}
 for(let b of bodies){ctx.save();ctx.translate(b.x,b.y);ctx.rotate(-.8);ctx.fillStyle='#05090caa';ctx.beginPath();ctx.ellipse(0,10,23,9,0,0,TAU);ctx.fill();ctx.fillStyle=b.color;rounded(-18,-11,36,22,10);ctx.fill();ctx.fillStyle='#122229';rounded(-7,-16,20,12,5);ctx.fill();ctx.fillStyle='#7edce4';rounded(-5,-14,15,7,3);ctx.fill();ctx.fillStyle='#ff5964';ctx.font='bold 14px sans-serif';ctx.fillText('×',24,-16);ctx.restore()}
 for(let c of crew)if(c.alive)drawCrew(c);drawPlayer();
 for(let p of particles){ctx.globalAlpha=clamp(p.t/.55,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,3,0,TAU);ctx.fill()}ctx.globalAlpha=1;
 // lighting mask: darkness boosts stealth but limits sight
 if(blackout>0){ctx.fillStyle='#02070bea';ctx.fillRect(camera.x,camera.y,cw,ch);let g=ctx.createRadialGradient(player.x,player.y,50,player.x,player.y,280);g.addColorStop(0,'#00000000');g.addColorStop(1,'#000000d8');ctx.fillStyle=g;ctx.fillRect(camera.x,camera.y,cw,ch);ctx.save();ctx.globalCompositeOperation='destination-out';let spot=ctx.createRadialGradient(player.x,player.y,35,player.x,player.y,210);spot.addColorStop(0,'#000');spot.addColorStop(1,'#0000');ctx.fillStyle=spot;ctx.fillRect(camera.x,camera.y,cw,ch);ctx.restore()}
 ctx.restore();drawMini();}
function drawMini(){let mw=mini.clientWidth,mh=mini.clientHeight;mctx.clearRect(0,0,mw,mh);mctx.fillStyle='#0c1b22';mctx.fillRect(0,0,mw,mh);let sx=mw/W,sy=mh/H;mctx.fillStyle='#456069';for(let r of rooms)mctx.fillRect(r.x*sx,r.y*sy,r.w*sx,r.h*sy);mctx.fillStyle='#c8f26b';mctx.beginPath();mctx.arc(player.x*sx,player.y*sy,3,0,TAU);mctx.fill();mctx.fillStyle='#ff6870';for(let c of crew)if(c.alive){mctx.beginPath();mctx.arc(c.x*sx,c.y*sy,2.4,0,TAU);mctx.fill()}mctx.strokeStyle='#ffffff44';mctx.strokeRect(camera.x*sx,camera.y*sy,cw*sx,ch*sy)}
function loop(now){if(!playing)return;let dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw();if(playing)requestAnimationFrame(loop)}
// Initial ambient scene behind the title card.
setup();camera.x=0;camera.y=0;draw();
})();
</script>
